#!/usr/bin/env node
/**
 * ULS LESS watcher (consumer-friendly)
 *
 * Why this exists:
 * - `vite build --watch` relies on Rollup watchers, which can become flaky in large LESS trees
 *   (dropped fs events / EMFILE / platform differences), so changes in overrides may not rebuild.
 * - This script compiles LESS to `dist/css/uls.css` + `dist/css/uls.min.css` and watches the
 *   user's styles/overrides directory directly, with a polling fallback.
 *
 * Intended usage (in any consumer repo that depends on uls-v2):
 * - `uls-watch-less`
 */

import { resolve } from 'path'
import {
  existsSync,
  mkdirSync,
  readFileSync,
  readdirSync,
  statSync,
  watch as fsWatch,
  writeFileSync,
} from 'fs'
import { createRequire } from 'module'
import less from 'less'

function loadUlsConfig(projectRoot) {
  try {
    const configPath = resolve(projectRoot, 'uls.config.cjs')
    if (!existsSync(configPath)) return {}
    const require = createRequire(import.meta.url)
    return require(configPath) || {}
  } catch {
    return {}
  }
}

function detectUlsPackagePath(projectRoot) {
  // Running in ULS repo itself
  if (existsSync(resolve(projectRoot, 'src/styles/uls-master.less'))) return projectRoot

  // Running in a consumer repo
  const nm = resolve(projectRoot, 'node_modules/uls-v2')
  if (existsSync(resolve(nm, 'src/styles/uls-master.less'))) return nm

  return null
}

async function compile({ entry, outDir, outFile, outMinFile, stylesPath, ulsPackagePath }) {
  if (!existsSync(entry)) throw new Error(`Entry file not found: ${entry}`)
  if (!existsSync(outDir)) mkdirSync(outDir, { recursive: true })

  const projectRoot = process.cwd()
  const src = readFileSync(entry, 'utf8')
  const entryDir = resolve(entry, '..')
  const nodeModulesPath = resolve(projectRoot, 'node_modules')

  const userStylesPath = resolve(projectRoot, stylesPath)
  const userOverridesPath = resolve(userStylesPath, 'overrides')
  const ulsStylesPath = resolve(ulsPackagePath, 'src/styles')
  const ulsOverridesPath = resolve(ulsStylesPath, 'uls-overrides/less/uls-primereact')

  const renderOpts = {
    filename: entry,
    paths: [
      entryDir,
      userStylesPath,
      userOverridesPath,
      ulsStylesPath,
      ulsOverridesPath,
      nodeModulesPath,
    ],
  }

  const cssResult = await less.render(src, renderOpts)
  writeFileSync(outFile, cssResult.css, 'utf8')
  console.log(`✅ LESS compiled → ${outFile}`)

  const minResult = await less.render(src, { ...renderOpts, compress: true })
  writeFileSync(outMinFile, minResult.css, 'utf8')
  console.log(`✅ LESS minified → ${outMinFile}`)
}

function debounce(fn, waitMs) {
  let t = null
  return (...args) => {
    if (t) clearTimeout(t)
    t = setTimeout(() => fn(...args), waitMs)
  }
}

function listLessFiles(rootDir) {
  const files = []
  const stack = [rootDir]
  while (stack.length) {
    const dir = stack.pop()
    let entries = []
    try {
      entries = readdirSync(dir, { withFileTypes: true })
    } catch {
      continue
    }
    for (const ent of entries) {
      const full = resolve(dir, ent.name)
      if (ent.isDirectory()) {
        stack.push(full)
      } else if (ent.isFile() && ent.name.endsWith('.less')) {
        files.push(full)
      }
    }
  }
  return files
}

async function main() {
  const projectRoot = process.cwd()
  const ulsConfig = loadUlsConfig(projectRoot)
  const stylesPath = ulsConfig.stylesPath || 'src/styles/uls'
  
  // Get app name from environment or config
  const appName = process.env.ULS_APP || ulsConfig.defaultApp || 'default'

  const ulsPackagePath = detectUlsPackagePath(projectRoot)
  if (!ulsPackagePath) {
    throw new Error(`Could not locate ULS styles. Expected either:
  - ${resolve(projectRoot, 'src/styles/uls-master.less')} (ULS repo)
  - ${resolve(projectRoot, 'node_modules/uls-v2/src/styles/uls-master.less')} (consumer repo)`)
  }

  const outDir = resolve(projectRoot, 'dist/css')
  const outFile = resolve(outDir, `uls-${appName}.css`)
  const outMinFile = resolve(outDir, `uls-${appName}.min.css`)

  // Prefer user's local per-app uls-master.less, otherwise fallback to package master/core.
  const userMaster = resolve(projectRoot, stylesPath, appName, 'uls-master.less')
  const pkgMaster = resolve(ulsPackagePath, 'src/styles/uls-master.less')
  const pkgLess = resolve(ulsPackagePath, 'src/styles/uls.less')
  const entry = existsSync(userMaster) ? userMaster : (existsSync(pkgMaster) ? pkgMaster : pkgLess)

  const userStylesDir = resolve(projectRoot, stylesPath, appName)
  const legacyOverridesDir = resolve(projectRoot, 'uls-overrides')

  // Watch roots:
  // - Consumer repos: watch user's styles directory (and legacy overrides if present).
  // - ULS repo: also watch ULS source LESS trees (uls-styles + uls-overrides), since
  //   contributors often edit those directly.
  const watchRoots = []
  if (existsSync(userStylesDir)) watchRoots.push(userStylesDir)
  if (existsSync(legacyOverridesDir)) watchRoots.push(legacyOverridesDir)

  const isUlsRepo = ulsPackagePath === projectRoot
  if (isUlsRepo) {
    const ulsStylesLessDir = resolve(projectRoot, 'src/styles/uls-styles/less')
    const ulsOverridesLessDir = resolve(projectRoot, 'src/styles/uls-overrides/less')
    if (existsSync(ulsStylesLessDir)) watchRoots.push(ulsStylesLessDir)
    if (existsSync(ulsOverridesLessDir)) watchRoots.push(ulsOverridesLessDir)
  }

  const doCompile = async () => {
    try {
      await compile({ entry, outDir, outFile, outMinFile, stylesPath, ulsPackagePath })
      console.log('✨ CSS updated automatically!')
    } catch (err) {
      console.error('❌ LESS build failed:', err?.message || err)
    }
  }

  await doCompile()

  if (watchRoots.length > 0) {
    console.log(`👀 Watching: ${watchRoots.join(', ')}`)
  } else {
    console.log(`⚠️  No watch roots found. Expected: ${userStylesDir}`)
  }
  console.log(`ℹ️  Entry: ${entry}`)

  const rebuild = debounce(doCompile, 150)

  const startPolling = () => {
    console.log('🕒 Falling back to polling mode for LESS changes (fs watchers unavailable)')
    const roots = watchRoots.length > 0 ? watchRoots : [userStylesDir]
    let lastMtimes = new Map()

    const scanOnce = () => {
      let changed = false
      const currentFiles = []

      for (const root of roots) {
        if (!existsSync(root)) continue
        const files = listLessFiles(root)
        for (const f of files) {
          currentFiles.push(f)
          let mtime = null
          try {
            mtime = statSync(f).mtimeMs
          } catch {
            if (lastMtimes.has(f)) {
              lastMtimes.delete(f)
              changed = true
            }
            continue
          }
          const prev = lastMtimes.get(f)
          if (prev == null) {
            lastMtimes.set(f, mtime)
            continue
          }
          if (mtime !== prev) {
            lastMtimes.set(f, mtime)
            changed = true
          }
        }
      }

      // Remove deleted files
      for (const known of Array.from(lastMtimes.keys())) {
        if (!currentFiles.includes(known)) {
          lastMtimes.delete(known)
          changed = true
        }
      }

      if (changed) {
        console.log('📝 Change detected (polling)')
        rebuild()
      }
    }

    scanOnce()
    setInterval(scanOnce, 750)
  }

  // Prefer a *small number* of recursive watchers (macOS supports this efficiently).
  // On platforms where recursive is unsupported, we fall back to polling.
  const watcherRoots = watchRoots.length > 0 ? watchRoots : [userStylesDir]
  const watchers = []
  let pollingStarted = false

  const stopWatchers = () => {
    for (const w of watchers) {
      try {
        w.close()
      } catch {
        // ignore
      }
    }
    watchers.length = 0
  }

  const switchToPolling = () => {
    if (pollingStarted) return
    pollingStarted = true
    stopWatchers()
    startPolling()
  }

  for (const root of watcherRoots) {
    if (!existsSync(root)) continue
    try {
      const w = fsWatch(root, { persistent: true, recursive: true }, (eventType, filename) => {
        const name = typeof filename === 'string' ? filename : ''
        // Some platforms may not provide filename; rebuild anyway on change/rename.
        if (eventType !== 'change' && eventType !== 'rename') return
        if (name && !name.endsWith('.less')) return
        console.log(`📝 Change detected: ${name || '(unknown file)'}`)
        rebuild()
      })
      w.on('error', (err) => {
        console.error('❌ Watcher error:', err?.message || err)
        switchToPolling()
      })
      watchers.push(w)
    } catch (err) {
      console.error('❌ Failed to start recursive watcher (falling back to polling).')
      console.error('   ', err?.message || err)
      switchToPolling()
      break
    }
  }

  if (watchers.length === 0 && !pollingStarted) {
    switchToPolling()
  }
}

main().catch((err) => {
  console.error('❌ uls-watch-less failed:', err?.message || err)
  process.exit(1)
})


